def catlink(i):return '/categories/'+CATS[i][0]+'/'
def toollink(t):return '/tools/'+t['slug']+'/'
def card(t,featured=False):
    pick=PICKS.get(t['slug'])
    return f"""<article class="card"><div class="cardtop"><span class="monogram">{E(t['name'][:2])}</span><span class="pill">{E(t['license'])}</span></div><h3><a href="{toollink(t)}">{E(t['name'])}</a></h3><p>{E(t['description'])}</p>{('<p class="picknote"><b>'+E(pick[0])+'</b><br>'+E(pick[1])+'</p>') if featured else ''}<div class="tags">{''.join(f'<a href="{catlink(i)}">{E(CATS[i][1])}</a>' for i in t['cats'])}</div><div class="cardfoot"><a href="{toollink(t)}">View profile <span aria-hidden="true">↗</span></a><button class="textbutton compare-add" data-slug="{t['slug']}" aria-pressed="false">+ Compare</button></div></article>"""
def crumbs(items):
    return '<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a>'+''.join(f' / '+(f'<a href="{u}">{E(n)}</a>' if u else f'<span aria-current="page">{E(n)}</span>') for n,u in items)+'</nav>'
themeboot="""<script>(function(){try{var t=localStorage.getItem("docatlas-theme");document.documentElement.dataset.theme=t==="dark"||t==="light"?t:matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light"}catch(e){document.documentElement.dataset.theme="light"}})();</script>"""
def page(path,title,desc,body,items=None,noindex=False,schema=None):
    canonical=BASE+path
    data=[{'@context':'https://schema.org','@type':'WebSite','name':'DocAtlas','url':BASE+'/','inLanguage':'en'}]
    if items:
        data.append({'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':n,'item':BASE+u} for i,(n,u) in enumerate([('Home','/')]+items)]})
    if schema:data.append(schema)
    out=OUT/(path.strip('/')+'/index.html' if path!='/' else 'index.html');out.parent.mkdir(parents=True,exist_ok=True)
    jsonld=json.dumps(data,ensure_ascii=True)
    out.write_text(f"""<!doctype html><html lang="en"><head><script async src="https://www.googletagmanager.com/gtm.js?id=GTM-WBMJ5QN3"></script>
<script>
  window.dataLayer = window.dataLayer || [];
  function gtag(){{dataLayer.push(arguments);}}
  gtag('js', new Date());
</script><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | DocAtlas</title><meta name="description" content="{E(desc)}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow'}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{E(title)} | DocAtlas"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="{canonical}"><meta name="theme-color" content="#183c2e"><link rel="icon" type="image/svg+xml" href="/favicon.svg">{themeboot}<link rel="stylesheet" href="/styles.css"><script type="application/ld+json">{jsonld}</script><script defer src="/app.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header><div class="navwrap"><a href="/" class="brand"><span class="logo" aria-hidden="true">▱</span>DocAtlas<span class="brandnote">THE DOCUMENT AI INDEX</span></a><nav aria-label="Main navigation"><a href="/categories/">Tasks</a><a href="/picks/">Featured Tools</a><a href="/methodology/">Methodology</a><a href="/compare/">Compare <span data-compare-count>0</span></a><button class="theme-toggle" id="theme-toggle" type="button" aria-label="Switch to dark mode" title="Switch to dark mode" aria-pressed="false"><span aria-hidden="true">☾</span></button><a class="navcta" href="/submit/">Submit a tool ↗</a></nav></div></header><main id="main">{body}</main><footer><div><a class="brand" href="/">DocAtlas</a><p>A curated field guide to document AI and semantic tooling.</p></div><nav aria-label="Footer"><a href="/categories/">All tasks</a><a href="/picks/">Featured Tools</a><a href="/methodology/">Editorial policy</a><a href="/submit/">Suggest a tool</a></nav><p class="fine">Source-informed. Limitations included. Make the final call with your own documents.</p></footer><div id="status" role="status" aria-live="polite"></div></body></html>""")
    if not noindex:urls.append(canonical)
def collection(path,name,desc,tools):
    return {'@context':'https://schema.org','@type':'CollectionPage','name':name,'url':BASE+path,'description':desc,'mainEntity':{'@type':'ItemList','itemListElement':[{'@type':'ListItem','position':i+1,'name':t['name'],'url':BASE+toollink(t)} for i,t in enumerate(tools)]}}
