page('/','Document AI Tools for Parsing, Extraction & Semantic Modeling','Compare 23 tools for OCR, structured extraction, document databases, ontology modeling, and multimodal RAG. Explore editorial picks and practical limitations.',f"""
<section class="hero"><div><p class="eyebrow">CURATED / DOCUMENT INTELLIGENCE</p><h1>Better tools for<br><em>complex documents.</em></h1><p class="herocopy">From scanned pages to structured data and shared meaning.<br>Find the right building blocks for your next workflow.</p><div class="herolinks"><a class="button light" href="#directory">Explore the directory ↗</a><a href="/methodology/">Our selection process →</a></div><div class="stats"><span><b>23</b> tools indexed</span><span><b>09</b> practical tasks</span><span>Human-curated</span></div></div><div class="docart" aria-hidden="true"><span class="artlabel">DOCUMENT → DATA → MEANING</span><div class="sheet sheet3"></div><div class="sheet sheet2"></div><div class="sheet sheet1"><div class="sheetheading"></div><div class="sheetlines"></div><div class="sheettable"></div><span>01 / SOURCE LAYERS</span></div><span class="artcaption">STRUCTURE WORTH KEEPING.</span></div></section>
<section class="picks-preview"><div class="sectionhead"><div><p class="eyebrow">A CONSIDERED STARTING POINT</p><h2>Featured Tools <span class="pill">6 selections</span></h2></div><a href="/picks/">See why we picked them →</a></div><div class="pickstrip">{''.join(f'<a href="{toollink(t)}"><span class="monogram">{E(t["name"][:2])}</span><span><b>{E(t["name"])}</b><small>{E(PICKS[t["slug"]][0])}</small></span><span class="arrow">↗</span></a>' for t in featured_tools)}</div><p class="fine">Selected for specific workflows from public documentation. Not a hands-on ranking. <a href="/methodology/">Read the evidence standard.</a></p></section>
<section id="directory" class="directory">{sidebar}<div class="results"><div class="searchbar"><label class="searchlabel"><span aria-hidden="true">⌕</span><input type="search" id="search" aria-label="Search tools, tasks, or capabilities" placeholder="Search tools, tasks, or capabilities…"><kbd>/</kbd></label><button id="toggle-filters" aria-expanded="false" aria-controls="filters">Filters <span aria-hidden="true">☷</span></button></div>{filters}<div class="sectionhead"><h2>All tools <span id="result-count" class="pill">23</span></h2><span class="eyebrow">THE TOOL INDEX</span></div><p class="intro fine">One profile per tool. Multiple task categories where they help.</p><div id="tool-grid" class="cards">{''.join(card(t) for t in TOOLS)}</div><div id="empty" hidden><h3>No tools match these filters.</h3><button id="empty-reset">Clear search and filters</button></div></div></section>""",schema=collection('/','Document AI tool directory','Curated tools for document processing and semantic workflows.',TOOLS))
page('/categories/','Browse Document AI Tools by Task','Explore nine task categories, from document parsing and field extraction to ontology modeling and visual retrieval.',crumbs([('Tasks',None)])+'<section class="pageintro"><p class="eyebrow">START WITH YOUR TASK</p><h1>The work comes first.</h1><p>Use these categories as a map, not a mandatory pipeline. A tool can belong to more than one task.</p></section><div class="categorygrid">'+''.join(f'<a class="categorycard" href="{catlink(i)}"><span class="eyebrow">TASK {i+1:02d}</span><h2>{E(c[1])} ↗</h2><p>{E(c[2])}</p><span class="fine">{sum(i in t["cats"] for t in TOOLS)} tools · {E(c[3])}</span></a>' for i,c in enumerate(CATS))+'</div>',items=[('Tasks','/categories/')])
for i,c in enumerate(CATS):
    tools=[t for t in TOOLS if i in t['cats']]
    resources='<div class="callout"><b>From records to shared meaning</b><p>Semantic tools may start with metadata or existing data, rather than raw documents. Source lineage is different from PDF page coordinates.</p><a href="https://www.w3.org/TR/owl2-overview/" rel="noopener" target="_blank">OWL 2: concepts and relationships ↗</a> · <a href="https://www.w3.org/TR/shacl/" rel="noopener" target="_blank">SHACL: RDF constraints ↗</a></div>' if i==6 else ''
    page(catlink(i),c[1]+' Tools',c[2],crumbs([('Tasks','/categories/'),(c[1],None)])+f'<section class="pageintro"><p class="eyebrow">TASK {i+1:02d} / {len(tools)} TOOLS</p><h1>{E(c[1])}</h1><p>{E(c[2])}</p><div class="tags">{E(c[3])}</div></section>'+resources+'<div class="cards">'+''.join(card(t) for t in tools)+'</div><nav class="relatednav" aria-label="Related task navigation">'+(f'<a href="{catlink(i-1)}">← {E(CATS[i-1][1])}</a>' if i else '<a href="/categories/">All tasks</a>')+(f'<a href="{catlink(i+1)}">{E(CATS[i+1][1])} →</a>' if i+1<len(CATS) else '<a href="/categories/">All tasks →</a>')+'</nav>',items=[('Tasks','/categories/'),(c[1],catlink(i))],schema=collection(catlink(i),c[1],c[2],tools))
def facts(t):
    return [('Input',t['input']),('Output',t['output']),('Provenance',t['provenance']),('Scanned pages',t['scans']),('Deployment',t['deployment']),('Availability',t['license']),('Costs to plan for',t['pricing'])]
for t in TOOLS:
    pick=PICKS.get(t['slug']);sem=SEM.get(t['slug']);others=[o for o in TOOLS if o!=t and set(o['cats'])&set(t['cats'])][:3]
    projectlink='<p><a href="https://hkustdial.github.io/DataMosaic/" target="_blank" rel="noopener">Explore the DataMosaic project site ↗</a></p>' if t['slug']=='datamosaic' else ''
    evidence=f'<div class="callout"><p class="eyebrow">DOCUMENTATION-BASED SELECTION</p><h2>Why it is a Featured Tool</h2><p>{E(pick[1])}</p><p><b>Before you choose:</b> {E(pick[2])}</p><a href="/picks/">See the shortlist and criteria →</a></div>' if pick else ''
    evidence+=projectlink
    evidence+=''.join('<p class="fine"><a href="'+E(u)+'" target="_blank" rel="noopener">'+E(n)+' ↗</a></p>' for n,u in EXTRA_SOURCES.get(t['slug'],[]))
    semantic=f'<section><h2>Semantic modeling profile</h2><p class="fine">{E(sem[0])}</p><div class="tags">{E(" · ".join(sem[1]))}</div><h3>Representation and interoperability</h3><p>{E(sem[2])}</p><h3>Updates and versioning</h3><p>{E(sem[3])}</p></section>' if sem else ''
    page(toollink(t),t['name']+' — Capabilities, Outputs & Limitations',t['description'],crumbs([('Tasks','/categories/'),(CATS[t['cats'][0]][1],catlink(t['cats'][0])),(t['name'],None)])+f'<section class="toolhero"><div><p class="eyebrow">{E(CATS[t["cats"][0]][1])}</p><h1>{E(t["name"])}</h1><p>{E(t["description"])}</p><div class="tags">'+''.join(f'<a href="{catlink(i)}">{E(CATS[i][1])}</a>' for i in t['cats'])+f'</div></div><div class="toolactions"><a class="button" href="{E(t["source"])}" target="_blank" rel="noopener">Official source ↗</a><button class="compare-add" data-slug="{t["slug"]}" aria-pressed="false">+ Compare</button></div></section><div class="detailgrid"><div>{evidence}<section><h2>At a glance</h2><dl>'+''.join(f'<dt>{E(k)}</dt><dd>{E(v)}</dd>' for k,v in facts(t))+f'</dl></section>{semantic}<section><h2>Limitations to check</h2><p>{E(t["limits"])}</p><h3>Build a meaningful sample</h3><p>'+('Test ambiguous terms, conflicting metric definitions, source mappings, and schema changes. Check how revisions affect the same workload.' if sem else 'Include your hardest pages: low-quality scans, missing fields, dense tables, and evidence split across pages. Validate output correctness separately from citation accuracy.')+f'</p></section></div><aside class="sourcebox"><p class="eyebrow">EVIDENCE & CONTEXT</p><h2>Check the source.</h2><p>This profile summarizes public project documentation. No independent benchmark or hands-on performance claim is made.</p><a href="{E(t["source"])}" target="_blank" rel="noopener">Read official documentation ↗</a><p class="fine">Documentation checked: {t["checked"]}<br>Evidence level: source review</p><a href="/methodology/">Our editorial method →</a></aside></div><section class="related"><div class="sectionhead"><h2>Related tools</h2><a href="{catlink(t["cats"][0])}">Explore this task →</a></div><div class="cards">'+''.join(card(o) for o in others)+'</div></section>',items=[('Tasks','/categories/'),(CATS[t['cats'][0]][1],catlink(t['cats'][0])),(t['name'],toollink(t))])
picks=featured_tools
page('/picks/',"Featured Tools: Six Tools for Document & Data Workflows",'Six source-reviewed starting points for conversion, grounded extraction, spreadsheet workflows, research Q&A, document databases, and evolving semantics.',crumbs([("Featured Tools",None)])+'<section class="pageintro"><p class="eyebrow">SELECTED WITH A PURPOSE</p><h1>Six tools. Six useful starting points.</h1><p>A shortlist for distinct jobs, with the reasoning left in. These are documentation-based selections, not a performance ranking.</p></section><div class="callout"><b>What earns a place?</b><p>Clear task fit, public technical evidence, understandable outputs, practical deployment information, and limitations a reader can check. Selection is editorial; placement is not sold.</p><a href="/methodology/">Read the full selection policy →</a></div><div class="callout"><b>Why this shortlist changed</b><p>Reviewed November 12, 2026. We considered task fit, public technical evidence, inspectable results, setup effort, and overlap. Lido adds spreadsheet-oriented operations; Atlas Workspace adds ready-to-use cited research answers.</p><p>PaddleOCR remains a candidate for a custom OCR stack; ColPali remains a candidate for building visual retrieval. Both stay in the directory. Their specialist roles are less direct starting points for this six-tool shortlist.</p><p><a href="/tools/paddleocr/">Explore PaddleOCR ↗</a> · <a href="/tools/colpali/">Explore ColPali ↗</a></p><p>Choose Lido for spreadsheet workflows or LandingAI ADE for grounded extraction APIs. Choose Atlas Workspace for a research app or ColPali for a retrieval component. These are workflow distinctions, not measured quality rankings.</p></div>'+''.join(f'<section class="pickrow"><div><span class="eyebrow">0{i+1} / {E(PICKS[t["slug"]][0])}</span><h2><a href="{toollink(t)}">{E(t["name"])} ↗</a></h2><p>{E(PICKS[t["slug"]][1])}</p></div><div><h3>What to verify</h3><p>{E(PICKS[t["slug"]][2])}</p>'+ ('<p><a href="https://hkustdial.github.io/DataMosaic/" target="_blank" rel="noopener">Project site and demo ↗</a></p>' if t['slug']=='datamosaic' else '') +f'<a href="{E(t["source"])}" target="_blank" rel="noopener">Official source ↗</a><p class="fine">Source review · 2026-11-12 · Not independently tested</p></div></section>' for i,t in enumerate(picks)),items=[("Featured Tools",'/picks/')],schema=collection('/picks/',"Featured Tools",'Six source-informed selections for distinct document and data tasks.',picks))
page('/methodology/','Editorial Methodology & Selection Policy','Learn how DocAtlas scopes its directory, selects editorial picks, handles evidence, and documents limitations.',crumbs([('Methodology',None)])+"""<article class="prose"><p class="eyebrow">THE EDITORIAL STANDARD</p><h1>Trust comes from showing the work.</h1><p class="lede">DocAtlas helps engineers make a smaller, better-informed shortlist. Public evidence and visible limitations are the starting point.</p><h2>What belongs here</h2><p>Tools that directly support document parsing, extraction, structured records, semantic modeling, retrieval, or grounded answers. Semantic foundations may take metadata and structured data rather than raw files.</p><p>General chat interfaces, annotation-only platforms, and broad office suites fall outside this directory.</p><h2>How profiles are built</h2><ol><li>Check the official project or product source.</li><li>Identify the task, inputs, outputs, and runtime dependencies.</li><li>Separate confirmed documentation from claims that need sample validation.</li><li>Record limitations and link readers back to the original source.</li></ol><h2>What a Featured Tool means</h2><p>A pick is useful for a named workflow and has enough public detail to evaluate. We consider task fit, technical documentation, outputs and attribution, deployment, licensing, and inspectable limitations. It is not a claim that the tool beats all alternatives.</p><h2>Evidence levels</h2><p><b>Source review:</b> a summary of official documentation. Current profiles and picks use this level. <b>Hands-on evaluation:</b> reserved for future work with published samples, versions, methods, and results. We do not label a source review as a test.</p><h2>Commercial relationships</h2><p>Editorial placement is not for sale. This edition contains no paid placements or affiliate links. Any future sponsorship or affiliate relationship must be disclosed beside the affected link or placement.</p><h2>How to read capabilities</h2><p>Code availability, model weights, and commercial rights are separate questions. Page citations, bounding boxes, semantic evidence, and database lineage are different forms of provenance.</p><h2>Corrections and updates</h2><p>Source-review dates describe documentation checks, not a promise of continuous monitoring. If a capability or link has changed, email a correction through the submission page. Suggestions remain unpublished until editorial review.</p><a class="button" href="/submit/">Prepare a correction or suggestion →</a></article>""",items=[('Methodology','/methodology/')])
page('/compare/','Compare Document AI Tools','Compare up to four tools by input, output, deployment, provenance, and practical limitations.',crumbs([('Compare',None)])+'<section class="pageintro"><p class="eyebrow">YOUR SHORTLIST</p><h1>Compare the trade-offs.</h1><p>Add two to four tools from the directory. Your list stays in this browser.</p></section><noscript><p>Interactive comparison requires JavaScript. Every <a href="/categories/">tool profile</a> is available without it.</p></noscript><div id="comparison"></div>',noindex=True)
page('/submit/','Submit a Tool — Email Submission Guidelines','What to include when suggesting a document AI tool. Email submissions, corrections, and suggestions to document.ai.tool@gmail.com.',crumbs([('Submit',None)])+'<article class="prose submit-guide"><p class="eyebrow">CONTRIBUTE TO DOCATLAS</p><h1>Submit a tool.</h1><p class="lede">Help others find useful tools for documents, data, and semantics.</p><div class="callout"><b>Submit by email</b><p>Send your submission to <a href="mailto:document.ai.tool@gmail.com">document.ai.tool@gmail.com</a>. We review submissions against our <a href="/methodology/">editorial policy</a> before listing them.</p><a class="button" href="mailto:document.ai.tool@gmail.com?subject=DocAtlas%20tool%20submission&body=Tool%20name%3A%0AOfficial%20URL%3A%0AOne-sentence%20tagline%3A%0APrimary%20category%3A%0AWorkflow%20stage%28s%29%3A%0APricing%20model%20and%20costs%3A%0AOpen-source%20license%20and%20GitHub%20URL%20%28if%20applicable%29%3A%0AOfficial%20documentation%3A%0ADemo%20or%20reproducible%20example%3A%0AImportant%20limitations%3A%0AProduct%20contact%3A%0ACurrent%20pricing%20URL%3A%0A">Open submission email ↗</a><p class="fine">Opens a draft in your email app. Review it and send when ready.</p></div><h2>What to include</h2><ul class="submission-list"><li><b>Name, URL, and a one-sentence tagline.</b> Explain the specific job your tool does.</li><li><b>Which category it belongs to.</b> Choose a primary category from our <a href="/categories/">nine task categories</a>; add related categories if useful.</li><li><b>Which workflow stage it helps with.</b> Select one or more stages below and explain the input and expected result.</li><li><b>Pricing and availability.</b> State whether it is Free, Free trial, Freemium, Subscription, Usage-based, or Enterprise quote. Mark Open source separately, specify the license, and note hosting, compute, or external model costs.</li><li><b>A GitHub link if open-source.</b> Include relevant code and model licenses.</li><li><b>Official documentation, a demo, and important limitations.</b> Link to a working demo or reproducible example; note format limits, output structure, provenance, and deployment requirements.</li><li><b>A product contact and a link to current pricing.</b> For free projects, link to the license or page confirming availability instead.</li></ul><h2>Workflow stages</h2><p>A stage describes where the tool helps in a workflow. Stages can overlap and do not need to be used in sequence.</p><div class="stage-list"><span>Document intake, classification & splitting</span><span>Parsing & OCR</span><span>Layout & table reconstruction</span><span>Schema-based field extraction</span><span>Format conversion & database construction</span><span>Ontology & semantic modeling</span><span>Multimodal retrieval & RAG</span><span>Visual document understanding</span><span>Agentic orchestration, verification & repair</span></div><h2>Suggestions and corrections</h2><p>Have a suggestion, a correction, or another idea? Contact <a href="mailto:document.ai.tool@gmail.com?subject=DocAtlas%20suggestion%20or%20correction">document.ai.tool@gmail.com</a>. Include the relevant page and supporting links when possible.</p><p class="fine">Submission does not guarantee inclusion or featured placement. Editorial placement is not for sale.</p></article>',noindex=True)
